        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.behaviorHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                emotionChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.behaviorHistory },
                        { data: ds.regulationHistory },
                        { data: ds.messageHistory },
                        { data: ds.resistanceHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 single source of truth - verbatim v1.0.0 formula (scoring unchanged).
            const behavior = Math.round(ds.behavior);
            const regulation = Math.round(ds.regulation);
            const message = Math.round(ds.message);
            const resistance = Math.round(ds.resistance);
            const behaviorScore = Math.max(0, Math.min(100, (behavior / this.TARGET_BEHAVIOR) * 70));
            const base = Math.round(behaviorScore * 0.42 + regulation * 0.22 + message * 0.18 + (100 - resistance) * 0.18);
            // v1.2.0: a guarantee that came due carries a credibility charge, so the number agrees with the verdict.
            return Math.max(0, Math.min(100, base - (ds.promiseDue ? this.CREDIBILITY_CHARGE : 0)));
        }

        _outcome(ds) {
            return Math.round(Math.max(0, Math.min(100, (Math.round(ds.behavior) / this.TARGET_BEHAVIOR) * 70)));
        }

        _process(ds) {
            return Math.round((Math.round(ds.regulation) + Math.round(ds.message) + (100 - Math.round(ds.resistance))) / 3);
        }

        _tier(ds) {
            // v1.2.0: one function, band from the score. The top band also states the three gates it implies.
            const c = this._composite(ds);
            const gates = Math.round(ds.behavior) >= this.TARGET_BEHAVIOR && !ds.oneOff && !ds.overPromised
                && Math.round(ds.regulation) >= 55 && Math.round(ds.resistance) <= 45;
            if (c >= this.TIER_TOP && gates) return 'grade_durable';
            if (c >= this.TIER_SOLID) return 'grade_solid';
            if (c >= this.TIER_MIXED) return 'grade_mixed';
            return 'grade_short';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const behavior = Math.round(ds.behavior);
            const regulation = Math.round(ds.regulation);
            const message = Math.round(ds.message);
            const resistance = Math.round(ds.resistance);

            // Composite: hitting the behavior target dominates, then regulation,
            // message fit, and low resistance.
            const behaviorScore = Math.max(0, Math.min(100, (behavior / this.TARGET_BEHAVIOR) * 70));
            const composite = this._composite(ds);

            const hitTarget = behavior >= this.TARGET_BEHAVIOR;
            const durable = !ds.oneOff && regulation >= 55 && resistance <= 45;
            const credible = !ds.overPromised && regulation >= 55;
            const backfired = ds.fearReached && resistance >= 60;

            const performanceKey = this._tier(ds);
            const performanceLabel = window.mySimulation.t(performanceKey);
            const met = (performanceKey === 'grade_durable');
            const T = (k) => window.mySimulation.t(k);

            // Diagnosis chips: what kind of run it was. They never decide the band.
            const chips = [];
            if (hitTarget && durable && credible) chips.push('grade_builttolast');
            if (hitTarget && ds.oneOff) chips.push('grade_spike');
            if (backfired) chips.push('grade_backfired');
            if (resistance >= 70) chips.push('grade_hardened');
            if (ds.promiseDue) chips.push('cm_chip_credibility');

            // Insights, built from what this run did. Mistakes first, most costly first.
            const insights = [];
            if (met) insights.push(T('insight_durable'));
            else if (backfired) insights.push(T('insight_backfire'));
            else if (ds.oneOff && hitTarget) insights.push(T('insight_spike'));
            else if (ds.oneOff) insights.push(T('insight_oneoffmiss'));
            else insights.push(T('insight_short'));

            if (ds.overPromised) insights.push(T('insight_overpromise'));
            if (ds.fearReached) insights.push(T('insight_fearframe'));
            if (ds.diagnosis === 'info') insights.push(T('insight_inforeflex'));
            else if (ds.diagnosis === 'opposition') insights.push(T('insight_oppositionread'));
            if (ds.factForFeeling) insights.push(T('insight_factfeeling'));
            if (resistance <= 30 && regulation >= 60 && !ds.overPromised) insights.push(T('insight_trusted'));
            if (!hitTarget) insights.push(T('insight_belowtarget'));
            else insights.push(T('insight_attarget'));
            if (ds.spendMultiplier != null) insights.push(T('insight_multiplier').replace('{m}', this._fmtNum(ds.spendMultiplier)));
            insights.length = Math.min(insights.length, 5);

            // Turning point: the round where the index gained least (or lost most), from the run's own record.
            let turning = null;
            const rs = ds.roundScores || [];
            if (rs.length) {
                // Shortfall against the gains of the reference play (teaching note path A: 36, 45, 57, 71, 95).
                let worst = 0, worstGap = null, best = 0, bestGain = null;
                for (let i = 0; i < rs.length; i++) {
                    const gain = rs[i] - (i === 0 ? this.START_SCORE : rs[i - 1]);
                    const gap = (this.REF_GAINS[i] || 0) - gain;
                    if (worstGap === null || gap > worstGap) { worstGap = gap; worst = i; }
                    if (bestGain === null || gain > bestGain) { bestGain = gain; best = i; }
                }
                const pick = met ? best : worst;
                // A guarantee is charged a round after it is made: point at the round where it was made.
                const at = (!met && ds.promiseDue && pick === 3) ? 2 : pick;
                turning = {
                    round: at + 1,
                    kind: met ? 'best' : 'worst',
                    from: (at === 0 ? this.START_SCORE : rs[at - 1]),
                    to: rs[at],
                    moveKey: (ds.roundKeys || [])[at] || 'sum_default',
                    delayed: (!met && ds.promiseDue && pick === 3)
                };
            }

            return {
                behavior: behavior,
                regulation: regulation,
                message: message,
                resistance: resistance,
                hitTarget: hitTarget,
                durable: durable,
                credible: credible,
                backfired: backfired,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                outcome: this._outcome(ds),
                process: this._process(ds),
                credibilityCharge: ds.promiseDue ? this.CREDIBILITY_CHARGE : 0,
                performance: performanceKey,
                performanceLabel: performanceLabel,
                performanceKey: performanceKey,
                met: met,
                chips: chips,
                turning: turning,
                insights: insights
            };
        }

        _fmtNum(v) {
            const lang = (window.vcI18n && window.vcI18n._lang) || 'en';
            const txt = Number(v).toFixed(2);
            return lang === 'es' ? txt.replace('.', ',') : txt;
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performanceKey ? t(s.performanceKey) : (s.performanceLabel || '');
            const badges = [];
            if (s.met) badges.push('<span class="emotionsim-cm-badge emotionsim-cm-met">' + t('cm_met') + '</span>');
            if (s.hitTarget === false) badges.push('<span class="emotionsim-cm-badge emotionsim-cm-fail">' + t('cm_fail_target') + '</span>');
            if (s.durable === false) badges.push('<span class="emotionsim-cm-badge emotionsim-cm-fail">' + t('cm_fail_durable') + '</span>');
            (s.chips || []).forEach((k) => {
                badges.push('<span class="emotionsim-cm-badge ' + (k === 'grade_builttolast' ? 'emotionsim-cm-met' : 'emotionsim-cm-fail') + '">' + t(k) + '</span>');
            });
            const kpi = (label, val) => '<div class="emotionsim-cm-metric"><div class="emotionsim-cm-metric-val">' + val + '</div><div class="emotionsim-cm-metric-lbl">' + label + '</div></div>';
            const kpis = kpi(t('cm_behavior'), (s.behavior != null ? Math.round(s.behavior) : 0) + '%')
                + kpi(t('cm_regulation'), (s.regulation != null ? Math.round(s.regulation) : 0))
                + kpi(t('cm_message'), (s.message != null ? Math.round(s.message) : 0))
                + kpi(t('cm_resistance'), (s.resistance != null ? Math.round(s.resistance) : 0))
                + kpi(t('cm_outcome'), (s.outcome != null ? s.outcome : 0) + '/100')
                + kpi(t('cm_process'), (s.process != null ? s.process : 0) + '/100')
                + kpi(t('cm_index'), score + '/100');
            const insights = (s.insights || []).map((x) => '<li>' + x + '</li>').join('');
            let turning = '';
            if (s.turning) {
                const tp = s.turning;
                const body = t(tp.kind === 'best' ? 'cm_turning_best' : (tp.delayed ? 'cm_turning_delayed' : 'cm_turning_worst'))
                    .replace('{r}', tp.round).replace('{name}', t('round_name_r' + tp.round)).replace('{move}', t(tp.moveKey))
                    .replace('{from}', tp.from).replace('{to}', tp.to);
                turning = '<div class="emotionsim-cm-insights emotionsim-cm-turning"><div class="emotionsim-cm-insights-title">' + t('cm_turning_title') + '</div><p>' + body + '</p></div>';
            }
            const charge = s.credibilityCharge ? '<p class="emotionsim-cm-note">' + t('cm_charge_note').replace('{n}', s.credibilityCharge) + '</p>' : '';
            const questions = '<div class="emotionsim-cm-insights emotionsim-cm-questions"><div class="emotionsim-cm-insights-title">' + t('cm_questions_title') + '</div><ol>'
                + '<li>' + t('cm_q1') + '</li><li>' + t('cm_q2') + '</li><li>' + t('cm_q3') + '</li></ol></div>';
            return '<div class="emotionsim-cm">'
                + '<div class="emotionsim-cm-head"><div class="emotionsim-cm-title">' + t('cm_title') + '</div>'
                + '<div class="emotionsim-cm-scorewrap"><span class="emotionsim-cm-score">' + score + '</span><span class="emotionsim-cm-score-max">/100</span></div>'
                + '<div class="emotionsim-cm-grade">' + grade + '</div>'
                + '<div class="emotionsim-cm-badges">' + badges.join('') + '</div></div>'
                + '<div class="emotionsim-cm-metrics">' + kpis + '</div>' + charge
                + turning
                + '<div class="emotionsim-cm-insights"><div class="emotionsim-cm-insights-title">' + t('cm_insights_title') + '</div><ul>' + insights + '</ul></div>'
                + questions
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.fearReached && ds.resistance >= 60) return window.mySimulation.t(`hint_fear`);
            if (ds.promiseDue) return window.mySimulation.t(`hint_overpromise`);
            if (ds.oneOff) return window.mySimulation.t(`hint_oneoff`);
            if (ds.resistance >= 65) return window.mySimulation.t(`hint_resistance`);
            if (state.currentPeriod >= 3 && ds.behavior < 35) return window.mySimulation.t(`hint_behavior`);
            if (ds.behavior >= 50 && ds.resistance <= 35 && ds.regulation >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

